#!/bin/zsh
# 录音来源标识：录音豆 / Mac / iPhone / 录音卡 / 导入，列表每行和详情头都能一眼看出是哪台设备录的。
cd "$(dirname "$0")"
gen() {
  local name=$1; local prompt=$2
  [ -f "$name.png" ] && return
  local t0=$(date +%s)
  codex exec --skip-git-repo-check --ephemeral -c 'model_reasoning_effort="low"' -C "$PWD" -s workspace-write \
    "请使用内置的 image_gen 工具生成一张高保真 UI 设计稿（像设计师在 Figma 里做的最终稿截图，正视图、不要透视、纯浅灰背景上只放这一个窗口）：$prompt 生成后把最终图片复制到当前目录，命名为 $name.png，然后只回复文件名。" < /dev/null > "$name.log" 2>&1
  echo "$name $(( $(date +%s) - t0 ))s $([ -f $name.png ] && echo ok || echo FAIL)"
}
S="这是 macOS 桌面应用「豆仓」（把录音转成文字、整理成纪要）。浅色模式。设计语言：苹果 macOS 最新系统的风格加乔纳森·艾维式的克制——圆角卡片、细分隔线、说明是小号灰字、对齐严谨、留白舒服。配色严格限定：暖灰纸色背景（#FAF9F7）、卡片纯白、深暖灰文字（#1C1917）、唯一强调色玫瑰红（#F43F5E，用在主按钮、选中状态）；绝对不要蓝色、紫色、青色、彩虹色。界面文字全部是简体中文，字体像苹方，清晰可读、没有乱码。"
gen ui_source "【录音来源标识】一个 macOS 窗口宽约 1260，三栏：左边窄侧栏（小仓鼠头像「豆仓」、玫瑰红「开始录音」按钮、总览/录音 21/素材/语音输入/知识库，项目、标签分组，底部设备卡「soundcore Work · 已连接」和齿轮按钮）。中间是录音列表栏：标题「全部录音 21 条」，搜索框，筛选胶囊「全部 · 星标 · 有待办 · 有重点」，再加一个小下拉「来源：全部」。列表按日期分组（「今天」「11月13日 周五」），每条是白色圆角卡片：左边场景小图标（灯泡/会议人像/波形，暖灰底），标题粗体一到两行，下面一行灰色小字「14:18 · 0:24 · 灵感」，**灰色小字最前面有一个很小的来源标识**：单色线条图标 + 两三个字，放在浅暖灰小胶囊里（#F5F5F4 底、#78716C 字），比如「(耳机形状图标) 录音豆」「(笔记本电脑图标) Mac」「(手机图标) iPhone」「(卡片图标) 录音卡」「(下载箭头图标) 导入」；卡片右下角是两个关键词小标签。列表里至少出现录音豆、Mac、导入三种来源，被选中的那张卡片是玫瑰红细描边。右边详情栏：顶部一行元信息「(会议图标) 会议 · (耳机图标) 录音豆 soundcore Work · 11月13日 18:40 · 39 分钟」，其中来源是同样的小胶囊，鼠标悬停时出现一个小提示气泡「在录音豆上录的，连上 Mac 后同步过来」；下面大标题「学校宣传片逐帧修改评审与测评文章改稿」，右侧分段控件「纪要 / 文字稿 / 改写」，再下面是 #标签 和白色「摘要」卡片。整体克制，来源标识不抢标题。$S"
